### Link to the code that reproduces this issue

https://codesandbox.io/p/sandbox/nervous-darkness-ldltfm

### To Reproduce



Here's a page that reproduces the issue. I've tried to trim this down to a minimal reproduction.

```tsx
const arrayBooleanFilter = (values: string[]) => {
  const truthy: string[] = [];
  for (const v of values) {
    if (v) {
      truthy.push(v);
    }
  }
  return truthy;
};

const identityIfTruthy = (location: string) => {
  if (location) return location;
};

const getTestResults = () => {
  const truthyValues = arrayBooleanFilter(["1", "", "2"]);
  const result = [];
  for (const value of truthyValues) {
    // if (value) { // Replacing with the following line fixes the issue.
    if (identityIfTruthy(value)) {
      result.push(value); // This code is commented out as it's deemed to be a constant falsy block
    }
  }
  return result;
};

export default function Home() {
  return (
    <>
      <p>
        Expected: <code>{`["1", "2"]`}</code>
      </p>
      <p>
        Result: <code>{JSON.stringify(getTestResults())}</code>
      </p>
    </>
  );
}
```

### Current vs. Expected behavior

The code should be detected as not a constant falsy check.

